"use strict";(self.webpackChunk=self.webpackChunk||[]).push([[778],{2571(e,n,t){t.r(n),t.d(n,{assets:()=>d,contentTitle:()=>s,default:()=>u,frontMatter:()=>o,metadata:()=>i,toc:()=>l});const i=JSON.parse('{"id":"extension/integrated_gradients","title":"Integrated Gradients","description":"Integrated Gradients","source":"@site/../docs/extension/integrated_gradients.md","sourceDirName":"extension","slug":"/extension/integrated_gradients","permalink":"/captum/docs/extension/integrated_gradients","draft":false,"unlisted":false,"editUrl":"https://github.com/meta-pytorch/captum/edit/master/docs/../docs/extension/integrated_gradients.md","tags":[],"version":"current","frontMatter":{"id":"integrated_gradients","title":"Integrated Gradients"},"sidebar":"docs","previous":{"title":"The Captum Contribution Process","permalink":"/captum/docs/contribution_guidelines"}}');var r=t(4848),a=t(8453);const o={id:"integrated_gradients",title:"Integrated Gradients"},s=void 0,d={},l=[{value:"Integrated Gradients",id:"integrated-gradients",level:2},{value:"Description",id:"description",level:3},{value:"More details on how to apply integrated gradients on larger DNN networks can be found here",id:"more-details-on-how-to-apply-integrated-gradients-on-larger-dnn-networks-can-be-found-here",level:4}];function c(e){const n={a:"a",code:"code",h2:"h2",h3:"h3",h4:"h4",li:"li",p:"p",pre:"pre",ul:"ul",...(0,a.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.h2,{id:"integrated-gradients",children:"Integrated Gradients"}),"\n",(0,r.jsx)(n.p,{children:"This section of the documentation shows how to apply integrated gradients on\nmodels with different types of parameters and inputs using Captum."}),"\n",(0,r.jsx)(n.h3,{id:"description",children:"Description"}),"\n",(0,r.jsxs)(n.p,{children:[(0,r.jsx)(n.a,{href:"https://arxiv.org/pdf/1703.01365.pdf",children:"Integrated gradients"})," is a simple, yet powerful axiomatic attribution method that requires almost no modification of the original network. It can be used for augmenting accuracy metrics, model debugging and feature or rule extraction."]}),"\n",(0,r.jsxs)(n.p,{children:["Captum provides a generic implementation of integrated gradients that can be used with any PyTorch model.\nIn this section of the tutorial we will describe how to apply integrated gradients for output predictions.\nHere is an example code snippet that reproduces the results from the ",(0,r.jsx)(n.a,{href:"https://arxiv.org/pdf/1703.01365.pdf",children:"original paper"})," (page 10)."]}),"\n",(0,r.jsx)(n.p,{children:"First, let's create a sample ToyModel, which computes a simple function on two inputs."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'import torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nclass ToyModel(nn.Module):\n    r"""\n    Example toy model from the original paper (page 10)\n\n    https://arxiv.org/pdf/1703.01365.pdf\n\n\n    f(x1, x2) = RELU(ReLU(x1) - 1 - ReLU(x2))\n    """\n\n    def __init__(self):\n        super().__init__()\n\n    def forward(self, input1, input2):\n        relu_out1 = F.relu(input1)\n        relu_out2 = F.relu(input2)\n        return F.relu(relu_out1 - 1 - relu_out2)\n'})}),"\n",(0,r.jsxs)(n.p,{children:["Second, let's apply integrated gradients on the toy model's output layer using sample data.\nThe code snippet below computes the attribution of output with respect to the inputs.\nThe ",(0,r.jsx)(n.code,{children:"attribute"})," method of ",(0,r.jsx)(n.code,{children:"IntegratedGradients"})," class returns input attributions which\nhave the same size and dimensionality as the inputs and an approximation error which\nis computed based on the completeness property of the integrated gradients.\nCompleteness property is one of the axioms that integrated gradients satisfies.\nIt states that the sum of the attributions must be equal to the difference between\nthe output of the DNN function F at the inputs and corresponding baselines.\nThe baselines also have the same shape and dimensionality as the inputs and if not\nprovided zero is used as default value."]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"from captum.attr import IntegratedGradients\nmodel = ToyModel()\n\n# defining model input tensors\ninput1 = torch.tensor([3.0], requires_grad=True)\ninput2 = torch.tensor([1.0], requires_grad=True)\n\n# defining baselines for each input tensor\nbaseline1 = torch.tensor([0.0])\nbaseline2 = torch.tensor([0.0])\n\n# defining and applying integrated gradients on ToyModel and the\nig = IntegratedGradients(model)\nattributions, approximation_error = ig.attribute((input1, input2),\n                                                 baselines=(baseline1, baseline2),\n                                                 method='gausslegendre',\n                                                 return_convergence_delta=True)\noutput\n\n...................\n\nattributions: (tensor([1.5000], grad_fn=<MulBackward0>),\n               tensor([-0.5000], grad_fn=<MulBackward0>))\n\napproximation_error (aka delta): 1.1801719665527344e-05\n"})}),"\n",(0,r.jsxs)(n.p,{children:["Now let's look at a simple classification model. The network architecture of this\nclassification model is based on the network described in:\n",(0,r.jsx)(n.a,{href:"https://adventuresinmachinelearning.com/pytorch-tutorial-deep-learning/",children:"https://adventuresinmachinelearning.com/pytorch-tutorial-deep-learning/"})]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'import torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nclass ToySoftmaxModel(nn.Module):\n    r"""\n    Model architecture from:\n\n    https://adventuresinmachinelearning.com/pytorch-tutorial-deep-learning/\n    """\n\n    def __init__(self, num_in, num_hidden, num_out):\n        super().__init__()\n        self.num_in = num_in\n        self.num_hidden = num_hidden\n        self.num_out = num_out\n        self.lin1 = nn.Linear(num_in, num_hidden)\n        self.lin2 = nn.Linear(num_hidden, num_hidden)\n        self.lin3 = nn.Linear(num_hidden, num_out)\n        self.softmax = nn.Softmax(dim=1)\n\n    def forward(self, input):\n        lin1 = F.relu(self.lin1(input))\n        lin2 = F.relu(self.lin2(lin1))\n        lin3 = self.lin3(lin2)\n        return self.softmax(lin3)\n'})}),"\n",(0,r.jsx)(n.p,{children:"Now, let's apply integrated gradients on the toy classification model defined\nabove using inputs that contain a range of numbers. We also choose an arbitrary\ntarget class (target_class_index: 5) which we use to attribute our predictions to.\nSimilar to the previous example, the output of attribution is a tensor with the same\ndimensionality as the inputs and an approximation error computed based on the\ncompleteness property of integrated gradients."}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"from captum.attr import IntegratedGradients\nnum_in = 40\ninput = torch.arange(0.0, num_in * 1.0, requires_grad=True).unsqueeze(0)\n\n# 10-class classification model\nmodel = ToySoftmaxModel(num_in, 20, 10)\n\n# attribution score will be computed with respect to target class\ntarget_class_index = 5\n\n# applying integrated gradients on the SoftmaxModel and input data point\nig = IntegratedGradients(model)\nattributions, approximation_error = ig.attribute(input, target=target_class_index,\n                                    return_convergence_delta=True)\n\n# The input and returned corresponding attribution have the\n# same shape and dimensionality.\n\noutput\n\n...................\n\nattributions: (tensor([[ 0.0000,  0.0014,  0.0012,  0.0019,  0.0034,  0.0020, -0.0041,  \n          0.0085, -0.0016,  0.0111, -0.0114, -0.0053, -0.0054, -0.0095,  0.0097, -0.0170,\n          0.0067,  0.0036, -0.0296,  0.0244,  0.0091, -0.0287,  0.0270,  0.0073,\n         -0.0287,  0.0008, -0.0150, -0.0188, -0.0328, -0.0080, -0.0337,  0.0422,\n          0.0450,  0.0423, -0.0238,  0.0216, -0.0601,  0.0114,  0.0418, -0.0522]],\n       grad_fn=<MulBackward0>),)\n\napproximation_error (aka delta): 0.00013834238052368164\n\nassert attributions.shape == input.shape\n"})}),"\n",(0,r.jsxs)(n.p,{children:["Now, let's look at a model that besides input tensors takes input arguments of\nother types. In practice this can be used to pass the sequence length or the\nword/token indices in a sequence of a text, for instance. The example below\ndemonstrates how to use ",(0,r.jsx)(n.code,{children:"additional_forward_args"}),". In this particular example\n",(0,r.jsx)(n.code,{children:"additional_forward_args"})," represents a single integer value.\nThose arguments are passed as ",(0,r.jsx)(n.code,{children:"additional_forward_args"})," to the ",(0,r.jsx)(n.code,{children:"attribute"})," method and\nthey will be passed to the model's forward function followed by inputs in the order\nprovided in ",(0,r.jsx)(n.code,{children:"additional_forward_args"}),". In the example below, we also demonstrate\nhow to apply integrated gradients to a batch of samples. The first dimension of\nthe input corresponds to the batch size.\nIn this case, batch size is equal to two."]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:'import torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nclass ToyModel_With_Additional_Forward_Args(nn.Module):\n    r"""\n        Slightly modified example model from the paper\n        https://arxiv.org/pdf/1703.01365.pdf\n        f(x1, x2) = RELU(ReLU(x1 - 1) - ReLU(x2))\n    """\n    def __init__(self):\n        super().__init__()\n    def forward(self, input1, input2, index):\n        relu_out1 = F.relu(input1 - 1)\n        relu_out2 = F.relu(input2)\n        return F.relu(relu_out1 - relu_out2)[:, index]\n'})}),"\n",(0,r.jsxs)(n.p,{children:["Now, let's apply integrated gradients on the model defined above and specify\n",(0,r.jsx)(n.code,{children:"additional_forward_args"})," parameter in addition to others."]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"from captum.attr import IntegratedGradients\n\ninput1 = torch.tensor([[1.0, 3.0], [3.0, 5.0]], requires_grad=True)\ninput2 = torch.tensor([[1.0, 4.0], [0.0, 2.0]], requires_grad=True)\n# Initializing our toy model\nmodel = ToyModel_With_Additional_Forward_Args()\n# Applying integrated gradients on the input\nig = IntegratedGradients(model)\n(input1_attr, input2_attr), delta = ig.attribute((input1, input2), n_steps=100,\n                                    additional_forward_args=1, return_convergence_delta=True)\noutput\n.........\ninput1_attr: tensor([[0.0000, 0.0000],\n                     [0.0000, 3.3428]], grad_fn=<MulBackward0>)\ninput2_attr:  tensor([[ 0.0000,  0.0000],\n                      [0.0000, -1.3371]], grad_fn=<MulBackward0>)\napproximation_error (aka delta): 0.005693793296813965\n"})}),"\n",(0,r.jsxs)(n.p,{children:["In addition to the parameters described above integrated gradients also allows to specify\nintegral approximation type with the argument ",(0,r.jsx)(n.code,{children:"method"})," which accepts the following values:\n",(0,r.jsx)(n.code,{children:"riemann_right"}),", ",(0,r.jsx)(n.code,{children:"riemann_left"}),", ",(0,r.jsx)(n.code,{children:"riemann_middle"}),", ",(0,r.jsx)(n.code,{children:"riemann_trapezoid"})," and ",(0,r.jsx)(n.code,{children:"gausslegendre"}),".\nThe latter approximates the fastest and is used as a default approximation  method.\nBesides approximation type the user can also specify the number of approximation\nsteps using ",(0,r.jsx)(n.code,{children:"n_steps"})," input argument. The latter can be used to find a tradeoff\nbetween approximation speed and the accuracy."]}),"\n",(0,r.jsx)(n.h4,{id:"more-details-on-how-to-apply-integrated-gradients-on-larger-dnn-networks-can-be-found-here",children:"More details on how to apply integrated gradients on larger DNN networks can be found here"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:(0,r.jsx)(n.a,{href:"/docs/tutorials/CIFAR_TorchVision_Interpret",children:"A simple classification model and CIFAR Dataset"})}),"\n",(0,r.jsx)(n.li,{children:(0,r.jsx)(n.a,{href:"/docs/tutorials/TorchVision_Interpret",children:"Torchvision's ResNet18 Model using handpicked images"})}),"\n",(0,r.jsx)(n.li,{children:(0,r.jsx)(n.a,{href:"/docs/tutorials/IMDB_TorchText_Interpret",children:"Sentiment classification model using TorchText and IMDB Dataset"})}),"\n",(0,r.jsx)(n.li,{children:(0,r.jsx)(n.a,{href:"/docs/tutorials/Multimodal_VQA_Interpret",children:"Visual Question Answering Model"})}),"\n",(0,r.jsx)(n.li,{children:(0,r.jsx)(n.a,{href:"/docs/tutorials/Titanic_Basic_Interpret",children:"A simple DNN with 2 hidden layers and Titanic Dataset"})}),"\n"]})]})}function u(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},8453(e,n,t){t.d(n,{R:()=>o,x:()=>s});var i=t(6540);const r={},a=i.createContext(r);function o(e){const n=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:o(e.components),i.createElement(a.Provider,{value:n},e.children)}}}]);